  ? `portfel ${pct(port.razem.wynikPct)}`
  : '';
const subject = ['WIG20 — przegląd ' + dzis, bilans, wynikTematu, nieswieze.length ? '⚠️ dane nieświeże' : '']
  .filter(Boolean)
  .join(' · ');

return [{ json: { html, text, subject } }];

// Portfolio stage. Two jobs, deliberately split:
//   1. ARITHMETIC (here, in code): current value, P/L, weights. Same rule as the bucket
//      counters — there is no reason to let a prompt get multiplication wrong.
//   2. JUDGEMENT (the model): what to do with each position, given the plan.
// The LLM receives the numbers already computed and is forbidden from recomputing them.
//
// The proxy is called straight from this node instead of a separate HTTP node so that an
// empty portfolio simply skips the call — a Code node returning no items would halt the
// chain and the whole e-mail would never be sent.
const spolki = $('Build ranking prompt').first().json.spolki;
const zrodlo = $('Fetch data (sequential)').all().map((i) => i.json);
const portfel = (zrodlo[0] && zrodlo[0].portfel) || [];

if (!portfel.length) {
  return [{ json: { pozycje: [], podsumowanie: [], razem: null, porada: '', pominiete: [], skipped: true } }];
}

const cena = {};
const jakosc = {};
for (const z of zrodlo) { cena[z.ticker] = z.price; jakosc[z.ticker] = z.quality || null; }

// GPW quotes in PLN, .US tickers in USD. Totals are grouped per currency — adding
// złoty to dollars would produce a confident, wrong number.
const waluta = (t) => (String(t).endsWith('.US') ? 'USD' : 'PLN');

// Ta sama spółka kupiona w kilku transzach to JEDNA pozycja z kilkoma zakupami, a nie
// kilka niezależnych pozycji: udział w portfelu, decyzja i ryzyko dotyczą całego pakietu.
// Ceny wejścia poszczególnych transz nie giną — jadą dalej w `zakupy`, bo to one mówią,
// która część pakietu jest pod wodą.
const wgTickera = new Map();
for (const p of portfel) {
  if (!wgTickera.has(p.ticker)) { wgTickera.set(p.ticker, []); }
  wgTickera.get(p.ticker).push(p);
}

const pozycje = [...wgTickera.entries()].map(([ticker, transze]) => {
  const kurs = typeof cena[ticker] === 'number' ? cena[ticker] : null;
  const szt = transze.reduce((a, t) => a + t.szt, 0);
  const koszt = transze.reduce((a, t) => a + t.szt * t.cena_kupna, 0);
  const srednia = koszt / szt;
  const wartosc = kurs === null ? null : szt * kurs;
  const wynik = wartosc === null ? null : wartosc - koszt;
  const wynikPct = wartosc === null ? null : ((kurs - srednia) / srednia) * 100;
  const s = spolki.find((x) => String(x.ticker).toUpperCase() === ticker) || null;
  const daty = transze.map((t) => t.data).filter(Boolean).sort();
  const notatki = [...new Set(transze.map((t) => t.notatka).filter(Boolean))];
  return {
    ticker,
    szt,
    cena_kupna: srednia,
    data: daty[0] || '',
    notatka: notatki.join(' · '),
    zakupy: transze.map((t) => ({
      szt: t.szt,
      cena_kupna: t.cena_kupna,
      data: t.data || '',
      notatka: t.notatka || '',
      wynikPct: kurs === null ? null : ((kurs - t.cena_kupna) / t.cena_kupna) * 100,
    })),
    waluta: waluta(ticker),
    kurs,
    koszt,
    wartosc,
    wynik,
    wynikPct,
    quality: jakosc[ticker] || null,
    bucket: s ? s.bucket : null,
    line: s ? s.line : null,
    horizons: s ? s.horizons : null,
    brakDanych: kurs === null,
  };
});

// Weights need ONE base, otherwise a single USD position shows as 100% of "the portfolio".
// NBP rates already ride along in /macro, so everything is converted to PLN for the split.
// Cost is converted at today's rate too: the result is therefore the return in the quote
// currency, with the FX move since purchase deliberately left out (we do not know the
// rate paid back then). The e-mail says so, so nobody reads it as a złoty return.
const macro = (zrodlo[0] && zrodlo[0].macro) || {};
const kursy = { PLN: 1 };
for (const f of (Array.isArray(macro.fx) ? macro.fx : [])) {
  if (f && f.code && Number.isFinite(Number(f.rate))) { kursy[String(f.code).toUpperCase()] = Number(f.rate); }
}
const dataKursu = ((Array.isArray(macro.fx) ? macro.fx : []).find((f) => f && f.code === 'USD') || {}).date || null;
for (const p of pozycje) {
  const fx = kursy[p.waluta];
  p.fx = fx || null;
  p.wartoscPln = p.wartosc !== null && fx ? p.wartosc * fx : null;
  p.kosztPln = fx ? p.koszt * fx : null;
}

// Kept alongside the PLN total: seeing the USD sleeve separately is genuinely useful.
const podsumowanie = [...new Set(pozycje.map((p) => p.waluta))].map((w) => {
  const grupa = pozycje.filter((p) => p.waluta === w && p.wartosc !== null);
  const wartosc = grupa.reduce((a, p) => a + p.wartosc, 0);
  const koszt = grupa.reduce((a, p) => a + p.koszt, 0);
  return {
    waluta: w,
    pozycji: grupa.length,
    wartosc,
    koszt,
    wynik: wartosc - koszt,
    wynikPct: koszt > 0 ? ((wartosc - koszt) / koszt) * 100 : null,
  };
});
const zWycena = pozycje.filter((p) => p.wartoscPln !== null);
const wartoscPln = zWycena.reduce((a, p) => a + p.wartoscPln, 0);
const kosztPln = zWycena.reduce((a, p) => a + p.kosztPln, 0);
const razem = {
  wartosc: wartoscPln,
  koszt: kosztPln,
  wynik: wartoscPln - kosztPln,
  wynikPct: kosztPln > 0 ? ((wartoscPln - kosztPln) / kosztPln) * 100 : null,
  pozycji: zWycena.length,
  waluty: [...new Set(pozycje.map((p) => p.waluta))],
  kurs_data: dataKursu,
  bezKursuWalut: [...new Set(pozycje.filter((p) => !p.fx).map((p) => p.waluta))],
};
for (const p of pozycje) {
  p.udzialPct = p.wartoscPln !== null && wartoscPln > 0 ? (p.wartoscPln / wartoscPln) * 100 : null;
}

const pominiete = pozycje.filter((p) => p.brakDanych).map((p) => p.ticker);

// ── prompt ────────────────────────────────────────────────────────────────────
const n2 = (x) => (x === null || x === undefined ? '?' : Number(x).toFixed(2));
// Pozycje są NUMEROWANE, bo ta sama spółka bywa kupiona w dwóch transzach po różnych
// cenach — bez numeru obie dostałyby jedną wspólną poradę.
const opisPozycji = pozycje.map((p, i) => {
  const h = (p.horizons || []).map((x) => `${x.code}=${x.verdict}`).join(' ');
  // Transze wypisane osobno tylko wtedy, gdy jest ich więcej niż jedna — wtedy model
  // widzi, że część pakietu jest pod wodą, a część nad, i może to wziąć pod uwagę.
  const transze = p.zakupy.length > 1
    ? `zakupy: ${p.zakupy.map((z) => `${z.szt} szt. po ${n2(z.cena_kupna)}${z.data ? ` z ${z.data}` : ''} (${n2(z.wynikPct)}%)`).join(', ')}`
    : '';
  return [
    `${i + 1}. ${p.ticker}: ŁĄCZNIE ${p.szt} szt., średnia cena ${n2(p.cena_kupna)} ${p.waluta}`,
    transze,
    `kurs ${n2(p.kurs)}, wartość ${n2(p.wartosc)} ${p.waluta}, wynik ${n2(p.wynik)} ${p.waluta} (${n2(p.wynikPct)}%)`,
    `udział ${n2(p.udzialPct)}% portfela`,
    p.notatka ? `notatka właściciela: ${p.notatka}` : '',
    p.line ? `ocena z przeglądu: ${p.bucket} ${p.line}` : 'brak analizy tej spółki w dzisiejszym przeglądzie',
    h ? `horyzonty: ${h}` : '',
  ].filter(Boolean).join('; ');
}).join('\n');

const opisSum = [
  `RAZEM (przeliczone na PLN po kursie NBP${razem.kurs_data ? ` z ${razem.kurs_data}` : ''}): ` +
  `wartość ${n2(razem.wartosc)} PLN, wynik ${n2(razem.wynik)} PLN (${n2(razem.wynikPct)}%)`,
  ...podsumowanie.map((s) =>
    `${s.waluta}: wartość ${n2(s.wartosc)}, koszt ${n2(s.koszt)}, wynik ${n2(s.wynik)} (${n2(s.wynikPct)}%)`),
].join('\n');

const prompt =
  `PORTFEL WŁAŚCICIELA (liczby policzone przez kod — NIE przeliczaj ich):\n${opisPozycji}\n\n` +
  `PODSUMOWANIE:\n${opisSum}\n\n` +
  `Notatki przy pozycjach to zapis intencji właściciela z dnia zakupu — traktuj je jak jego plan.\n\n` +
  (pominiete.length ? `BEZ AKTUALNEGO KURSU (nie oceniaj wyniku): ${pominiete.join(', ')}\n\n` : '') +
  `Odpowiedz w formacie:\n` +
  `###POZYCJE###\n` +
  `NR | TICKER | DZIAŁANIE | jedno zdanie uzasadnienia\n` +
  `(NR to numer pozycji z listy powyżej. DZIAŁANIE: DOKUP / TRZYMAJ / REDUKUJ / SPRZEDAJ / ` +
  `OBSERWUJ. Jedna linia na pozycję. Spółka kupiona w kilku transzach to JEDNA pozycja — ` +
  `oceniasz cały pakiet, ale w uzasadnieniu możesz odnieść się do transzy, która wyróżnia ` +
  `się wynikiem.)\n` +
  `###PODSUMOWANIE###\n` +
  `2-4 zdania o całości: koncentracja, czy pozycje wciąż robią to, po co zostały kupione ` +
  `(patrz notatki), co zrobić w pierwszej kolejności.`;

const system =
  'Jesteś doradcą prowadzącym portfel właściciela na GPW i rynkach zagranicznych. ' +
  'Dostajesz JEGO pozycje z JUŻ POLICZONYMI liczbami, jego notatki z dnia zakupu oraz oceny ' +
  'spółek z dzisiejszego przeglądu.\n\n' +
  'ŻELAZNE ZASADY:\n' +
  '1. NIE PRZELICZAJ liczb — wartość, wynik i udziały są policzone przez kod. Cytuj je, ' +
  'nie licz własnych. Nie podawaj żadnej liczby, której nie ma w danych wejściowych.\n' +
  '2. Ocena spółki z przeglądu jest Twoim materiałem, ale decyzja o POZYCJI to co innego niż ' +
  'ocena spółki: bierz pod uwagę wielkość pozycji, średnią cenę zakupu i plan właściciela. ' +
  'Gdy pozycja ma kilka transz, to nadal JEDEN pakiet — nie proponuj sprzecznych działań ' +
  'dla różnych transz tej samej spółki.\n' +
  '3. Notatka przy pozycji to powód zakupu zapisany ręką właściciela. Odnieś się do niej ' +
  'wprost: czy ten powód dalej obowiązuje, czy się zdezaktualizował.\n' +
  '4. Pozycja bez aktualnego kursu: napisz „brak danych", nie zgaduj wyniku.\n' +
  '5. Bez superlatywów bez pokrycia i bez obietnic co do przyszłych kursów. Piszesz o ryzyku ' +
  'tak samo chętnie jak o okazji; podaj argument przeciw własnej radzie.\n' +
  '6. Zwięźle, po polsku. To analiza danych, NIE rekomendacja inwestycyjna.';

let porada = '';
let blad = '';
try {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:8787',
    body: { prompt, system, model: 'opus' },
    json: true,
    timeout: 600000,
  });
  porada = String((res && res.response) || '');
  if (!porada) { blad = String((res && res.error) || 'pusta odpowiedź z proxy'); }
} catch (e) {
  blad = String((e && e.message) || e);
}

return [{ json: { pozycje, podsumowanie, razem, porada, blad, pominiete, skipped: false } }];
